#include <stdio.h>

struct Mark { int roll; int score; };

struct Mark boosted(struct Mark input, int bonus)
{
    input.score += bonus;
    return input;
}

int main(void)
{
    struct Mark record = {5, 60};
    printf("Copy: %d Original: %d\n", boosted(record, 5).score, record.score);
    return 0;
}

#include <stdio.h>

struct Mark { int roll; int score; };

void add_bonus(struct Mark *record, int bonus)
{
    record->score += bonus;
}

int main(void)
{
    struct Mark record = {5, 60};
    add_bonus(&record, 5);
    printf("Updated: %d\n", record.score);
    return 0;
}

#include <stdio.h>

struct Mark { int roll; int score; };

struct Mark choose(struct Mark a, struct Mark b)
{
    if (b.score > a.score || (b.score == a.score && b.roll < a.roll)) {
        return b;
    }
    return a;
}

int main(void)
{
    struct Mark first = {8, 75};
    struct Mark second = {3, 75};
    struct Mark winner = choose(first, second);
    printf("Winner: %d %d\n", winner.roll, winner.score);
    return 0;
}

